# f05 常夜の戦場 - day_turns=0 でずっと夜のマップ。
# **夜は陸VS陸・海VS海・空VS空しか成立しない**ので、
# 戦闘機で地上を叩く／対空戦車で航空を落とす、といった支援が一切効かない。
# 陸・海・空がそれぞれ別の戦いを同時に進める形になる。
# 夜間ユニット（夜間忍兵・夜間突撃艦・夜間迎撃機）は攻撃+50%かつ視界が落ちず、
# 通常ユニットは攻撃-20%・視界-2・間接射程-1。夜専用部隊が主役になる。
# 中央の海の帯に橋は無く、陸は渡れない。180度回転対称。
[map]
name             = 常夜の戦場
width            = 44
height           = 28
turns            = 70
timeout_winner   = -1
night            = 1
day_turns        = 0
night_turns      = 5
funds0           = 3500
funds1           = 3500

